import math

def ap(rel, R):
    hits, total = 0, 0.0
    for i, r in enumerate(rel, 1):
        if r:
            hits += 1
            total += hits / i
    return total / R

def p_at(rel, k):
    return sum(rel[:k]) / k

def dcg(g):
    return sum(x / math.log2(i + 2) for i, x in enumerate(g))

def ndcg(g):
    return dcg(g) / dcg(sorted(g, reverse=True))

